dashboard.definition:
{
    "title": "Executive Overview",
    "description": "Executive overview across manufacturing, datacenter, network, collaboration and web, per site",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-60m@m,now"
            }
        },
        "input_site": {
            "type": "input.dropdown",
            "title": "Site",
            "options": {
                "items": [
                    {
                        "label": "All sites",
                        "value": "*"
                    },
                    {
                        "label": "Atlanta",
                        "value": "atlanta"
                    },
                    {
                        "label": "Berlin",
                        "value": "berlin"
                    },
                    {
                        "label": "Vienna",
                        "value": "vienna"
                    }
                ],
                "token": "site",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        }
    },
    "dataSources": {
        "ds_base": {
            "type": "ds.search",
            "options": {
                "query": "(index=demo_mes production_rate_per_hour=*) OR (index=demo_infra sensor_type IN (temperature, power)) OR (index=demo_mssql event_type=performance) OR (index=demo_thousendeyes sourcetype=\"thousendeyes:json\" thousandeyes.test.type IN (\"http-server\", \"api\", \"agent-to-agent\")) OR (index=demo_tomcat_logs) OR (index=demo_cisco_catalyst sourcetype=\"cisco:dnac:devicehealth\") OR (index=demo_cisco_meraki sourcetype=\"meraki:wirelessdevicespacketlossbydevice\") OR (index=demo_msteams event_type IN (call_ended, call_failed, call_queue_stats))\n| rex field=Location \"(?i)(?<cat_site>vienna|berlin|atlanta)\"\n| rex field=network.name \"(?i)^(?<mer_site>vienna|berlin|atlanta)\"\n| eval web_site=case(index!=\"demo_tomcat_logs\", null(), like(host, \"atl%\"), \"atlanta\", like(host, \"ber%\"), \"berlin\", like(host, \"vie%\"), \"vienna\")\n| eval site=lower(coalesce(cat_site, mer_site, web_site, 'thousandeyes.agent.location', location))\n| search site=\"$site$\"\n| eval te_type='thousandeyes.test.type'\n| eval web=if(te_type=\"http-server\", 'metric_name:http.server.request.availability', null()), api=if(te_type=\"api\", 'metric_name:api.completion', null()), dc_loss=if(te_type=\"agent-to-agent\", 'metric_name:network.loss', null())\n| eval temp=if(sensor_type=\"temperature\", value_celsius, null()), power=if(sensor_type=\"power\" AND like(sensor_id, \"%-power-total\"), value_kw, null())\n| eval req=if(index=\"demo_tomcat_logs\", 1, null()), err=if(index=\"demo_tomcat_logs\" AND status>=400, 1, null()), call=if(in(event_type, \"call_ended\", \"call_failed\"), 1, null()), call_ok=if(event_type=\"call_ended\", 1, null())\n| bin _time span=5m\n| stats avg(oee_pct) as oee avg(production_rate_per_hour) as rate avg(defect_rate_pct) as defect avg(temp) as temp avg(power) as power_avg dc(eval(if(isnotnull(power), sensor_id, null()))) as power_sensors avg(buffer_cache_hit_ratio) as cache avg(web) as web avg(api) as api avg(dc_loss) as dc_loss avg(HealthScore) as campus avg(downstream.lossPercentage) as wifi count(req) as req count(err) as err count(call) as calls count(call_ok) as calls_ok max(calls_waiting) as waiting by _time site",
                "enableSmartSources": true
            },
            "name": "All domains per site (5 min)"
        },
        "ds_k_oee": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m avg(oee) as \"OEE\""
            }
        },
        "ds_k_rate": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m avg(rate) as \"Units per hour\""
            }
        },
        "ds_k_defect": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m avg(defect) as \"Defect rate\""
            }
        },
        "ds_k_campus": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m avg(campus) as \"Campus health\""
            }
        },
        "ds_k_web": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m avg(web) as \"Web availability\""
            }
        },
        "ds_k_teams": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m sum(calls_ok) as ok sum(calls) as calls | eval \"Call success\"=if(calls > 0, round(100 * ok / calls, 1), null()) | fields _time \"Call success\""
            }
        },
        "ds_k_temp": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m avg(temp) as \"Rack temperature\""
            }
        },
        "ds_k_power": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| eval power=power_avg * power_sensors | timechart span=5m sum(power) as \"Facility power\""
            }
        },
        "ds_k_hotline": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m max(waiting) as \"Calls waiting\""
            }
        },
        "ds_k_err": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m sum(err) as err sum(req) as req | eval \"Web error rate\"=if(req > 0, round(100 * err / req, 1), null()) | fields _time \"Web error rate\""
            }
        },
        "ds_score": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| stats avg(campus) as campus avg(wifi) as wifi avg(dc_loss) as dc_loss avg(oee) as oee avg(defect) as defect avg(temp) as temp avg(cache) as cache avg(web) as web avg(api) as api sum(err) as err sum(req) as req sum(calls_ok) as calls_ok sum(calls) as calls by site\n| where in(site, \"atlanta\", \"berlin\", \"vienna\")\n| eval web_err=if(req > 0, round(100 * err / req, 1), null()), teams=if(calls > 0, round(100 * calls_ok / calls, 1), null())\n| eval Status=case(campus < 5 OR dc_loss >= 5 OR oee < 70 OR web < 95 OR teams < 85, \"Critical\", campus < 8 OR dc_loss >= 1 OR wifi > 2 OR oee < 85 OR web < 99 OR teams < 95, \"Degraded\", true(), \"Healthy\")\n| eval Site=upper(substr(site, 1, 1)).substr(site, 2)\n| eval \"Campus\"=round(campus, 1), \"Wi-Fi loss %\"=round(wifi, 1), \"DC loss %\"=round(dc_loss, 2), \"OEE %\"=round(oee, 1), \"Defect %\"=round(defect, 2), \"Temp °C\"=round(temp, 1), \"DB cache %\"=round(cache, 1), \"Web avail %\"=round(web, 1), \"API compl %\"=round(api, 1), \"Web err %\"=web_err, \"Teams OK %\"=teams\n| table Site Status \"Campus\" \"Wi-Fi loss %\" \"DC loss %\" \"Teams OK %\" \"OEE %\" \"Defect %\" \"Temp °C\" \"DB cache %\" \"Web avail %\" \"API compl %\" \"Web err %\""
            }
        },
        "ds_score_rings": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| stats avg(campus) as campus avg(dc_loss) as dc_loss avg(oee) as oee avg(web) as web by site\n| where in(site, \"atlanta\", \"berlin\", \"vienna\")\n| eval value=round(100 * (min(campus / 10, 1) * 0.35 + max(0, 1 - dc_loss / 5) * 0.25 + min(oee / 100, 1) * 0.2 + min(web / 100, 1) * 0.2), 0)\n| eval name=upper(substr(site, 1, 1)).substr(site, 2), unit=\"\", key=site, detail=\"Campus \".round(campus, 1).\" · DC loss \".round(dc_loss, 2).\" % · OEE \".round(oee, 0).\" % · Web \".round(web, 1).\" %\"\n| table name value unit detail key"
            }
        },
        "ds_t_campus": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where in(site, \"atlanta\", \"berlin\", \"vienna\") | timechart span=5m avg(campus) by site"
            }
        },
        "ds_t_rate": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where in(site, \"atlanta\", \"berlin\", \"vienna\") | timechart span=5m avg(rate) by site"
            }
        },
        "ds_t_web": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where in(site, \"atlanta\", \"berlin\", \"vienna\") | timechart span=5m avg(web) by site"
            }
        },
        "ds_t_err": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where in(site, \"atlanta\", \"berlin\", \"vienna\") | eval e=if(req > 0, 100 * err / req, null()) | timechart span=5m avg(e) by site"
            }
        },
        "ds_events": {
            "type": "ds.search",
            "options": {
                "query": "(index=demo_mes event_type=alarm (severity=critical OR severity=error) location=\"$site$\") OR (index=demo_mssql event_type=alert severity=critical location=\"$site$\") OR (index=demo_windows_events EventType=Error location=\"$site$\") OR (index=demo_msteams severity=high location=\"$site$\") OR (index=demo_thousendeyes sourcetype=\"thousendeyes:json\" thousandeyes.test.type=agent-to-agent metric_name:network.loss>=10 thousandeyes.agent.location=\"$site$\") OR (index=demo_cisco_catalyst sourcetype=\"cisco:dnac:devicehealth\" Reachability!=\"Reachable\") OR (index=demo_ai_defense sourcetype=\"cisco:ai:defense\" event_action=\"Block\") OR (index=demo_sap sourcetype=\"sap:idoc\" direction=outbound status=\"02\" target_location=\"$site$\") OR (index=demo_mes event_type=system_alert alert_type=order_data_missing location=\"$site$\")\n| rex field=Location \"(?i)(?<cat_site>vienna|berlin|atlanta)\"\n| eval Site=lower(coalesce(cat_site, target_location, 'thousandeyes.agent.location', location, \"global\"))\n| search Site=\"$site$\" OR Site=\"global\"\n| eval Source=case(index=\"demo_mes\", \"Manufacturing\", index=\"demo_mssql\", \"Database\", index=\"demo_windows_events\", \"Windows\", index=\"demo_msteams\", \"Teams\", index=\"demo_thousendeyes\", \"ThousandEyes\", index=\"demo_cisco_catalyst\", \"Catalyst Center\", index=\"demo_ai_defense\", \"AI Defense\", index=\"demo_sap\", \"SAP ERP\")\n| eval Asset=case(index=\"demo_sap\", rfc_destination, alert_type=\"order_data_missing\", \"All lines\", true(), coalesce(line_id, DeviceName, 'thousandeyes.test.name', user_name, mvindex(host, 0))), Severity=case(index=\"demo_ai_defense\", \"warning\", in(index, \"demo_mes\", \"demo_mssql\"), severity, index=\"demo_windows_events\", \"error\", in(index, \"demo_msteams\", \"demo_thousendeyes\"), \"high\", true(), \"critical\")\n| eval Description=case(index=\"demo_sap\", \"Production order IDoc not delivered to MII: \".message, alert_type=\"order_data_missing\", message, index=\"demo_mes\", alarm_description, index=\"demo_mssql\", message, index=\"demo_windows_events\", Message, index=\"demo_msteams\", coalesce(error_message, error), index=\"demo_thousendeyes\", \"Path loss \".round('metric_name:network.loss', 1).\" %\", index=\"demo_cisco_catalyst\", \"Device unreachable (health \".HealthScore.\")\", index=\"demo_ai_defense\", \"Prompt blocked by guardrail\")\n| dedup Source Asset Description\n| head 25\n| eval Time=strftime(_time, \"%H:%M:%S\")\n| table Time Severity Site Source Asset Description",
                "enableSmartSources": true
            },
            "name": "Recent critical events"
        },
        "ds_sap": {
            "type": "ds.search",
            "options": {
                "query": "(index=demo_sap sourcetype=\"sap:idoc:status\" target_location=\"$site$\") OR (index=demo_sap sourcetype=\"sap:mii:performance\" location=\"$site$\") OR (index=demo_sap sourcetype=\"sap:erp:performance\" dialog_response_time_ms=*)\n| eval plant=coalesce(target_location, if(sourcetype=\"sap:mii:performance\", location, \"erp\"))\n| bin _time span=5m\n| stats sum(idocs_created) as created sum(idocs_delivered) as delivered sum(idoc_error_count) as errors min(mii_order_buffer) as buffer avg(dialog_response_time_ms) as resp by _time plant",
                "enableSmartSources": true
            },
            "name": "SAP order interface (5 min)"
        },
        "ds_k_sap_delivered": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_sap",
                "query": "| timechart span=5m sum(created) as created sum(delivered) as delivered | eval \"Orders delivered\"=if(created > 0, min(100, round(100 * delivered / created, 1)), null()) | fields _time \"Orders delivered\""
            }
        },
        "ds_k_sap_errors": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_sap",
                "query": "| timechart span=5m sum(errors) as \"IDoc errors\""
            }
        },
        "ds_k_sap_buffer": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_sap",
                "query": "| timechart span=5m min(buffer) as \"MII order buffer\""
            }
        },
        "ds_k_sap_resp": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_sap",
                "query": "| timechart span=5m avg(resp) as \"ERP response\""
            }
        },
        "ds_t_sap_orders": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_sap",
                "query": "| where plant!=\"erp\" | timechart span=5m sum(delivered) by plant"
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "coolashaker_studio",
                        "dashboard": "cs_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_exec": {
